<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Gdpr\Domain\GdprSubjectData;
use Civi\Lughauth\Features\OAuth\Gdpr\Domain\GdprDataPackage;
use Civi\Lughauth\Features\OAuth\Gdpr\Domain\Exception\GdprException;
use Civi\Lughauth\Features\OAuth\Gdpr\Infrastructure\Driven\GdprDataAdapter;
use Civi\Lughauth\Features\OAuth\Gdpr\Domain\Gateway\GdprDataExportGateway;
use Civi\Lughauth\Features\OAuth\Gdpr\Domain\Gateway\GdprDataDeleteGateway;

final class GdprDomainUnitTest extends TestCase
{
    // --- GdprSubjectData ---

    public function test_gdpr_subject_data_stores_fields(): void
    {
        $s = new GdprSubjectData('profile', ['name' => 'Alice', 'email' => 'a@x.com']);
        $this->assertSame('profile', $s->context);
        $this->assertSame(['name' => 'Alice', 'email' => 'a@x.com'], $s->data);
    }

    // --- GdprDataPackage ---

    public function test_gdpr_data_package_to_array(): void
    {
        $at = new DateTimeImmutable('2026-01-15T10:00:00+00:00');
        $sections = [
            new GdprSubjectData('profile', ['name' => 'Bob']),
            new GdprSubjectData('sessions', ['count' => 5]),
        ];
        $pkg = new GdprDataPackage('user-1', 'tenant-a', $at, $sections);
        $arr = $pkg->toArray();

        $this->assertSame('user-1', $arr['subject_id']);
        $this->assertSame('tenant-a', $arr['tenant']);
        $this->assertSame($at->format(DateTimeInterface::ATOM), $arr['exported_at']);
        $this->assertArrayHasKey('profile', $arr['data']);
        $this->assertArrayHasKey('sessions', $arr['data']);
        $this->assertSame(['name' => 'Bob'], $arr['data']['profile']);
    }

    // --- GdprException ---

    public function test_gdpr_exception_unauthorized(): void
    {
        $ex = GdprException::unauthorized();
        $this->assertSame('access_denied', $ex->error());
        $this->assertSame(403, $ex->statusCode());
    }

    public function test_gdpr_exception_not_found(): void
    {
        $ex = GdprException::notFound();
        $this->assertSame('not_found', $ex->error());
        $this->assertSame(404, $ex->statusCode());
    }

    // --- GdprDataAdapter (composite) ---

    public function test_export_aggregates_all_contributors(): void
    {
        $c1 = new class () implements GdprDataExportGateway {
            public function exportForSubject(string $subjectId, string $tenant): array
            {
                return [new GdprSubjectData('profile', ['name' => 'Alice'])];
            }
        };
        $c2 = new class () implements GdprDataExportGateway {
            public function exportForSubject(string $subjectId, string $tenant): array
            {
                return [new GdprSubjectData('activity', ['logins' => 10])];
            }
        };

        $adapter = new GdprDataAdapter(exportContributors: [$c1, $c2]);
        $result = $adapter->exportForSubject('u1', 't1');

        $this->assertCount(2, $result);
        $this->assertSame('profile', $result[0]->context);
        $this->assertSame('activity', $result[1]->context);
    }

    public function test_export_returns_empty_when_no_contributors(): void
    {
        $adapter = new GdprDataAdapter();
        $this->assertSame([], $adapter->exportForSubject('u', 't'));
    }

    public function test_delete_calls_all_contributors(): void
    {
        $called = [];
        $c1 = new class ($called) implements GdprDataDeleteGateway {
            public function __construct(private array &$called)
            {
            }
            public function deleteForSubject(string $subjectId, string $tenant): void
            {
                $this->called[] = 'c1';
            }
        };
        $c2 = new class ($called) implements GdprDataDeleteGateway {
            public function __construct(private array &$called)
            {
            }
            public function deleteForSubject(string $subjectId, string $tenant): void
            {
                $this->called[] = 'c2';
            }
        };

        $adapter = new GdprDataAdapter(deleteContributors: [$c1, $c2]);
        $adapter->deleteForSubject('u1', 't1');

        $this->assertSame(['c1', 'c2'], $called);
    }
}
